    "전 서버 지휘관 100자 실시간 차원 교신 & 자유 소통": "Real-time cross-dimensional communication between commanders",
    "전 서버 지휘관 100자 실시간 교신 & 자유 소통": "Real-time cross-dimensional communication between commanders",
    "익명(게스트) 지휘관은 차원 메세지를 작성할 수 없습니다. 정식 계정으로 로그인해 주세요.": "Guest commanders cannot write dimensional messages. Please log in with a regular account.",
    "익명(게스트) 지휘관은 방명록을 작성할 수 없습니다. 정식 계정으로 로그인해 주세요.": "Guest commanders cannot write dimensional messages. Please log in with a regular account.",
    "차원 메세지 내용을 입력해 주세요.": "Please enter message content.",
    "차원 메세지는 최대 100자까지 작성할 수 있습니다.": "Dimensional messages can be up to 100 characters.",
    "차원 메세지 전송 중 오류가 발생했습니다.": "An error occurred while sending the dimensional message.",
    "방명록 등록 중 오류가 발생했습니다.": "An error occurred while sending the dimensional message.",
    "메세지 전송에 실패했습니다.": "Failed to send message.",
