    "번역 중...": "Translating...",
    "방주 프롤로그 시네마틱 영상 다시 보기": "Replay Ark Prologue Cinematic",
    "4막 구성의 세계관 시네마틱 컷씬 감상": "Watch the 4-act world lore cinematic cutscene",
    "방주 프롤로그 서사 다시 보기": "Replay Ark Prologue Narrative",
    "초반 세계관 및 작전 지침 서사": "Early world lore and operational briefing",
    "⚡ [진척도 가속] 윤회의 고리 100 위험도 점프 (위험도 +100 / 📜 초월 비전서 ×3 획득)": "⚡ [Progress Accelerated] Reincarnation Ring 100 Hazard Jump (Hazard +100 / 📜 Transcendence Grimoires x3 obtained)",
    "⚡ [진척도 극한 가속] 시간선을 강제로 뛰어넘어 상위 계층으로 직행했습니다! (무간도 위험도 +100 폭발적 도약, 전원 EXP +1,000)": "⚡ [Extreme Progress Acceleration] Forcibly leaped timelines straight to upper strata! (Avici Hazard +100 explosive surge, all allies EXP +1,000)",
    "🛡️ [안전 파밍] 차원의 닻으로 시공간 안정화 (위험도 -50 감소 / 전리품 분실률 0% 보존)": "🛡️ [Safe Farming] Stabilize spacetime with Dimensional Anchor (Hazard -50 / 0% loot loss rate preserved)",
    "🛡️ [안전 파밍] 무간도의 난류를 잠재워 전리품을 안전하게 보존했습니다. (무간도 위험도 -50 감소, 배낭 분실률 0%)": "🛡️ [Safe Farming] Calmed turbulence of Avici, safely preserving loot. (Avici Hazard -50, backpack loss rate 0%)",
    "🌟 [{0} 특기] 시공간 위상 정밀 조율 (위험도 -60 감소 & 🌌 공허 파편 ×5 획득)": "🌟 [{0} Specialty] Spacetime Phase Precision Tuning (Hazard -60 & 🌌 Void Shard x5 acquired)",
    "구출된 생존자 거주지. 방주에 세금(골드)을 정기 납부합니다. (1~5레벨 10% 감액, Lv.5부터 15% 감액, Lv.6 초과 시 레벨당 30% 추가 증산)": "Shelter for rescued survivors. Regularly pays taxes (Gold) to the Ark. (Lv.1~5: -10% cost, Lv.5+: -15% cost, Above Lv.6: +30% yield compound bonus per level)",
    "구출된 생존자 거주지. 방주에 세금(골드)을 정기 납부합니다. (1~5레벨 10% 감액, Lv.5부터 15% 감액, Lv.6 초과 시 레벨당 30% 추 증산)": "Shelter for rescued survivors. Regularly pays taxes (Gold) to the Ark. (Lv.1~5: -10% cost, Lv.5+: -15% cost, Above Lv.6: +30% yield compound bonus per level)",
    "구출된 생존자 거주지. 방주 세금(골드) 정기 납부합니다. (1~5레벨 10% 감액, Lv.5부터 15% 감액, Lv.6 초과 시 레벨당 30% 추 증산)": "Shelter for rescued survivors. Regularly pays taxes (Gold) to the Ark. (Lv.1~5: -10% cost, Lv.5+: -15% cost, Above Lv.6: +30% yield compound bonus per level)",
    "방주 외곽 목재 벌채 시설. 영지 증축과 성화 유지에 필요한 목재를 생산합니다. (Lv.5부터 골드 유지비 점진 감면: Lv.5 7% ~ Lv.10 42%)": "Ark outer timber mill. Produces wood required for citadel expansion & bonfire maintenance. (Lv.5+ Gold upkeep progressive discount: Lv.5 7% to Lv.10 42%)",
    "방주 외곽 목재 벌채 시설. 영지 증축과 성화 유지 필요한 목재를 생산합니다. (Lv.5부터 골드 유지비 점진 감면: Lv.5 7% ~ Lv.10 42%)": "Ark outer timber mill. Produces wood required for citadel expansion & bonfire maintenance. (Lv.5+ Gold upkeep progressive discount: Lv.5 7% to Lv.10 42%)",
    "부유성 지반 채굴 시설. 석재를 생산하며 Lv.3부터 철광석을 함께 발굴합니다. (Lv.5부터 골드 유지비 점진 감면, Lv.7부터 골드 유지비 30% 감축 및 식량 유지비 분담)": "Floating citadel bedrock quarry. Produces stone and excavates iron ore starting from Lv.3. (Lv.5+ Gold upkeep progressive discount; Lv.7+ 30% Gold upkeep reduction & shared Food upkeep)",
    "식량 정제 시설. Lv.3부터 가죽 추출, 전 레벨 틱당 생산량 80% 대폭 증산(Lv.1: 2, Lv.5: 16, Lv.10: 43) 및 [대량 배급제] 전 시설 식량 유지비 30% 감면합니다.": "Food refinery. Extracts leather from Lv.3, grants massive +80% production boost across all levels (Lv.1: 2, Lv.5: 16, Lv.10: 43), and [Mass Rationing] permanently reduces food upkeep by 30% for all facilities.",
    "용병 고용소. 방랑 용병을 계약 영입하며, 레벨이 오를수록 서브 퀘스트의 요구량과 보상(골드·에테르·마도석·보급품)이 강화되고 Lv.5부터 15초마다 식량(🍗)을 생산(2레벨마다 +4 증산: Lv.5=4, Lv.7=8, Lv.9=12)합니다.": "Mercenary guild. Contracts wandering heroes, enhances sub-quest requirements & rewards (Gold, Ether, Magic Stones, Supplies) as level rises, and produces Food(🍗) every 15s starting at Lv.5 (+4 boost every 2 levels: Lv.5=4, Lv.7=8, Lv.9=12).",
    "장비 공방. 전술 무기 및 방어구 단조, 장비 강화(+10강) 및 접두/접미 인챈트를 수행합니다. (Lv.4부터 에테르 유지비 외 4G~10G 골드 유지비 소모)": "Tactical armory. Forges weapons & armor, enhances equipment up to +10, and applies prefix/suffix enchantments. (Lv.4+ consumes 4G~10G Gold upkeep in addition to Ether upkeep)",
    "클래스 승격 시설. 1/2차 전직을 수행하며 Lv.2~5 기본 클래스 EXP 최대 +50%, Lv.6~10 1차 각성 클래스 EXP 최대 +40% 증폭합니다.": "Class promotion sanctuary. Conducts 1st/2nd class advancements; boosts Base Class EXP by up to +50% (Lv.2~5) and 1st Awakened Class EXP by up to +40% (Lv.6~10).",
    "에테르 연금 및 마도 시설. 에테르를 정기 생산하고 마도서 제작 및 최고 10레벨까지 강화할 수 있으며, Lv.6 시 [에테르 환류관] 마도 시설 에테르 유지비 30% 영구 감면합니다.": "Ether alchemy & magic lab. Regularly produces Ether, crafts and upgrades grimoires up to Lv.10, and at Lv.6 unlocks [Aether Feedback Pipe] to permanently discount magical facility Ether upkeep by 30%.",
    "PVP 차원 관문 및 월드 레이드. 비동기 랭킹 결투, Lv.3 시 『차원 네메시스』 레이드, Lv.6 증축 시 5인 차원 부대 타 영지 침공해 자원 30% 약탈하는 『차원 영지 침공』이 해금됩니다.": "PVP Dimensional Gate & World Raid. Unlocks asynchronous ranking duels, 『Dimension Nemesis』 World Raid at Lv.3, and 『Territory Invasion』 at Lv.6 to plunder 30% resources with a 5-hero strike team.",
    "PVP 차원 관문 및 월드 레이드. 비동기 랭킹 결투, Lv.3 시 『차원 네메시스』 레이드, Lv.6 증축 시 5인 차원 부대 타 영지 침공하는 『차원 영지 침공』 해금됩니다.": "PVP Dimensional Gate & World Raid. Unlocks asynchronous ranking duels, 『Dimension Nemesis』 World Raid at Lv.3, and 『Territory Invasion』 at Lv.6 to plunder 30% resources with a 5-hero strike team.",
