    "자신에게 120% 보호막 부여 (2턴)": "Grants 120% Barrier to self (2 turns)",
    "비전서: 응급 처치": "Grimoire: First Aid",
    "붕대와 약초를 사용하여 단일 아군의 HP를 30% 즉시 회복합니다.": "Uses bandages and herbs to immediately heal a single ally for 30% HP.",
    "단일 아군 HP 30% 즉시 회복": "Single ally: recovers 30% HP immediately",
