    "응축된 에테르 탄환을 날려 단일 적에게 144% 마법 피해를 입힙니다.": "Fires a condensed aether bolt, dealing 144% Magic DMG to an enemy.",
    "단일 적 144% 마법 피해": "Single enemy: 144% Magic DMG",
    "비전서: 도발의 함성": "Grimoire: Taunting Roar",
    "포효하여 적의 시선을 끌고 2턴간 자신의 방어력을 30% 증가시킵니다.": "Roars to draw enemy attention, increasing self DEF by 30% for 2 turns.",
