    "비전서: 화염구": "Grimoire: Fireball",
    "타오르는 화염구를 투척하여 단일 적에게 155% 화염 마법 피해와 화상을 부여합니다.": "Hurls a blazing fireball, dealing 155% Fire DMG and Burn to an enemy.",
    "화염구": "Fireball",
