    "비전서: 성역의 결계": "Grimoire: Sanctuary Barrier",
    "성스러운 결계를 펼쳐 아군 전체에 2턴간 받는 피해 15% 감소 효과를 부여합니다.": "Unfurls a holy barrier, reducing damage taken by all allies by 15% for 2 turns.",
    "성역의 결계": "Sanctuary Barrier",
    "아군 전체 받는 피해 15% 감소 (2턴)": "All allies: damage taken -15% (2 turns)",
    "비전서: 그림자 습격": "Grimoire: Shadow Ambush",
    "어둠 속에서 급습하여 180% 물리 피해를 입히고 1턴간 자신의 치명타율을 40% 올립니다.": "Ambushes from the dark for 180% Physical DMG; self Crit Rate +40% for 1 turn.",
    "단일 적 180% 피해 + 치명타율 40% 증가": "Single enemy: 180% DMG + Crit Rate +40%",
    "비전서: 마나 역류": "Grimoire: Mana Backsurge",
    "적의 마나를 교란하여 120% 마법 피해를 입히고 자신의 마나를 20 회복합니다.": "Disrupts enemy mana, dealing 120% Magic DMG and restoring 20 MP to self.",
    "마나 역류": "Mana Backsurge",
    "단일 적 120% 마법 피해 + 마나 20 회복": "Single enemy: 120% Magic DMG + 20 MP recovered",
    "비전서: 휠윈드": "Grimoire: Whirlwind",
    "무기를 크게 휘둘러 적 전체에 95% 물리 광역 피해를 가합니다.": "Swings weapon in a wide arc, dealing 95% AoE Physical DMG to all enemies.",
    "휠윈드": "Whirlwind",
    "적 전체 95% 물리 광역 피해": "All enemies: 95% AoE Physical DMG",
    "비전서: 신성한 빛": "Grimoire: Divine Light",
    "하늘에서 성광을 내려 아군 전체의 HP를 25% 회복시키고 디버프 1개를 정화합니다.": "Calls down holy radiance to heal all allies for 25% HP and cleanse 1 debuff.",
    "신성한 빛": "Divine Light",
    "아군 전체 HP 25% 회복 + 디버프 1개 정화": "All allies: heal 25% HP + cleanse 1 debuff",
    "비전서: 눈부신 섬광": "Grimoire: Blinding Flash",
    "강렬한 빛을 뿜어 적 전체에 60% 피해를 주고 2턴간 실명 상태로 만듭니다.": "Emits a blinding light dealing 60% DMG and blinding all enemies for 2 turns.",
    "눈부신 섬광": "Blinding Flash",
