    "적 전체 방어력 -35% 디버프 (2턴)": "All enemies DEF -35% debuff (2 turns)",
    "고대 성역을 전개하여 아군 전체에게 공격력 비례 180%의 대형 보호막을 씌웁니다.": "Deploys an ancient sanctuary, shielding all allies for 180% ATK.",
    "아군 전체 180% 보호막 전개 (3턴)": "All allies: 180% Barrier deployed (3 turns)",
    "비전서: 광기의 난무": "Grimoire: Frenzied Dance",
