    "응축된 마력을 일거에 터뜨려 적 전체에 161% 광역 비전 마법 피해를 가하고 2턴간 방어력을 35% 분쇄합니다.": "Detonates condensed mana, dealing 161% Arcane AoE DMG to all and shredding 35% DEF for 2 turns.",
