    "비전서: 플라즈마 파쇄포": "Grimoire: Plasma Breaker Cannon",
    "[후열 저격] 고압 플라즈마 탄환을 발사해 단일 적에게 220% 관통 피해를 입히고 2턴간 적 공격력 40% 약화 디버프를 부여합니다.": "[Backline Snipe] Fires high-voltage plasma round for 220% Piercing DMG and inflicts -40% ATK for 2 turns.",
