    "신성 성전: 발할라의 불멸": "Holy Scripture: Valhalla Immortality",
    "아군 전체에게 공격력 +50% 버프와 강력한 250% 보호막을 부여합니다.": "Grants all allies +50% ATK buff and an impenetrable 250% barrier.",
    "발할라의 불멸": "Valhalla Immortality",
    "태초의 성전: 창세의 성령": "Primordial Scripture: Genesis Holy Spirit",
