    "창세의 성령": "Genesis Holy Spirit",
    "아군 전체 HP 81% 회복 & 공격력 버프": "All allies: heal 81% HP & ATK buff",
    "비전서: 흑핵의 영구동결 [1F 보스]": "Grimoire: Core Permafrost [1F Boss]",
    "[기사·용병 계열 특화] 침묵의 흑핵 거신의 냉각 핵을 개방하여 단일 적에게 165% 빙결 피해를 입히고 1턴 완전 결빙(행동 불가) 및 전열 아군에게 150% 보호막을 부여합니다. (비적합 계열 사용 시 위력 50% 반감)": "[Knight/Swordsman Focus] Unlocks the colossus cooling core, dealing 165% Frost DMG to an enemy, 1-turn Freeze (stun), and grants front allies a 150% shield (50% power penalty if affinity mismatched).",
    "흑핵의 영구동결": "Core Permafrost",
