    "사령의 영혼 수확": "Phantom Soul Harvest",
    "[기사·용병 특화] 적 전체 110% 암흑 참격 + 피해량 35% 파티 전원 흡혈 치유": "[Knight/Swordsman Focus] All enemies: 110% Dark Slash + 35% total damage party heal",
    "비전서: 광맥의 마도 분출 [3F 보스]": "Grimoire: Vein Arcane Eruption [3F Boss]",
    "[기사·용병 계열 특화] 태고의 광맥 베히모스의 마도 화산력을 분출시켜 전열 적에게 175% 방어 무시 고열 폭발을 가하고 3턴간 화상(방어력 50% 분쇄)을 일으킵니다. (비적합 계열 사용 시 위력 50% 반감)": "[Knight/Swordsman Focus] Erupts primordial behemoth volcanic force, dealing 175% defense-ignoring fire blast to front foes and inflicting 3-turn Burn (-50% DEF) (50% power penalty if mismatched).",
    "광맥의 마도 분출": "Vein Arcane Eruption",
    "[기사·용병 특화] 전열 적 175% 방어무시 고열 폭발 + 3턴 화상/방어 50% 분쇄": "[Knight/Swordsman Focus] Front foes: 175% defense-ignoring fire blast + 3-turn Burn/DEF -50%",
    "비전서: 시공간 차원 붕괴 [4F 보스]": "Grimoire: Spacetime Dimensional Collapse [4F Boss]",
    "[마총·암살 계열 특화] 심연의 시공 왜곡자의 차원 닻을 투하하여 후열 적에게 180% 치명 저격을 가하고 적 전체의 속도를 2턴간 40% 감속시킵니다. (비적합 계열 사용 시 위력 50% 반감)": "[Gunner/Rogue Focus] Drops dimensional anchor on backline for 180% Crit Snipe and slows all enemies Speed by 40% for 2 turns (50% power penalty if mismatched).",
    "시공간 차원 붕괴": "Spacetime Dimensional Collapse",
    "[마총·암살 특화] 후열 적 180% 치명 차원 저격 + 적 전체 2턴 속도 40% 감속": "[Gunner/Rogue Focus] Back foe: 180% Crit Snipe + all enemies Speed -40% for 2 turns",
    "비전서: 원초의 공허 묵시록 [5F 보스]": "Grimoire: Primordial Void Apocalypse [5F Boss]",
    "[사제·마법 계열 특화] 공허의 침식자의 근원 마력을 해방하여 적 전체에 150% 공허 마법 피해를 입히고 모든 아군의 디버프를 즉시 정화하며 1턴간 완전 무적 결계를 전개합니다. (비적합 계열 사용 시 위력 50% 반감)": "[Priest/Mage Focus] Unleashes void core energy dealing 150% Void Magic DMG to all, cleanses all ally debuffs, and erects an invulnerable barrier for 1 turn (50% penalty if mismatched).",
    "원초의 공허 묵시록": "Primordial Void Apocalypse",
    "[사제·마법 특화] 적 전체 150% 공허 마법 피해 + 아군 디버프 전원 정화 & 1턴 무적 결계": "[Priest/Mage Focus] All enemies: 150% Void Magic DMG + cleanse all ally debuffs & 1-turn invulnerability",
    "비전서: 진홍의 피의 지배 [6F 보스]": "Grimoire: Crimson Blood Dominance [6F Boss]",
