    "진홍의 피의 지배": "Crimson Blood Dominance",
    "[기사·용병 특화] 단일 적 190% 흡혈 참격 + 적 전체 3턴 치명 출혈": "[Knight/Swordsman Focus] Single enemy: 190% Lifesteal Slash + 3-turn Bleed on all enemies",
    "비전서: 망각의 사신 낫 [7F 보스]": "Grimoire: Reaper Scythe of Oblivion [7F Boss]",
    "[마총·암살 계열 특화] 망각의 묘지기의 거대한 사신 낫을 휘둘러 후열 적에게 200% 초극딜 참격을 가하고 전열 적에게 2턴간 침묵과 기절을 유발합니다. (비적합 계열 사용 시 위력 50% 반감)": "[Gunner/Rogue Focus] Swings giant scythe dealing 200% devastating slash to back foes and inflicts 2-turn Silence/Stun on front foes (50% penalty if mismatched).",
    "망각의 사신 낫": "Reaper Scythe of Oblivion",
    "[마총·암살 특화] 후열 적 200% 초극딜 참격 + 전열 적 2턴 침묵/기절": "[Gunner/Rogue Focus] Back foes: 200% burst slash + front foes: 2-turn Silence/Stun",
    "비전서: 단죄의 칠흑 성역 [8F 보스]": "Grimoire: Pitch-Black Sanctuary of Condemnation [8F Boss]",
    "[사제·마법 계열 특화] 타락한 기사단장의 칠흑 성역을 전개하여 아군 전체에게 공격력 비례 250% 흡수 보호막을 생성하고 3턴간 공격력을 40% 증폭합니다. (비적합 계열 사용 시 위력 50% 반감)": "[Priest/Mage Focus] Erects dark sanctuary granting allies a 250% ATK barrier and amplifying ATK by 40% for 3 turns (50% penalty if mismatched).",
    "단죄의 칠흑 성역": "Pitch-Black Sanctuary of Condemnation",
    "[사제·마법 특화] 아군 전체 공격력 비례 250% 보호막 + 3턴간 공격력 40% 증폭 버프": "[Priest/Mage Focus] All allies: 250% ATK shield + 40% ATK buff for 3 turns",
    "비전서: 만화경 환영 폭풍 [9F 보스]": "Grimoire: Kaleidoscope Mirage Tempest [9F Boss]",
    "[마총·암살 계열 특화] 미궁의 지배자의 거울 차원을 개방하여 적 전체에 167% 마법 관통 피해를 입히고 2턴간 아군 전체에게 회피율 50% 버프를 부여합니다. (비적합 계열 사용 시 위력 50% 반감)": "[Gunner/Rogue Focus] Unlocks mirrored dimension dealing 167% Piercing Magic DMG to all and granting party +50% Evasion for 2 turns (50% penalty if mismatched).",
    "만화경 환영 폭풍": "Kaleidoscope Mirage Tempest",
    "[마총·암살 특화] 적 전체 167% 마법 관통 피해 + 2턴간 아군 전체 회피율 50% 증가": "[Gunner/Rogue Focus] All enemies: 167% Magic Piercing DMG + party Evasion +50% for 2 turns",
    "비전서: 종말의 심연 아마게돈 [10F 보스]": "Grimoire: Abyssal Armageddon of Ruin [10F Boss]",
    "[사제·마법 계열 특화] 심연의 군주 아스모데우스의 종말 권능을 소환하여 적 전체에 160% 신화급 파멸 피해를 퍼붓고 1턴 기절 및 5턴간 공허 침식(공격력/방어력 50% 감소)을 부여합니다. (비적합 계열 사용 시 위력 50% 반감)": "[Priest/Mage Focus] Summons Asmodeus doom power, dealing 160% mythic Ruin DMG to all, 1-turn Stun, and 5-turn Void Corruption (-50% ATK/DEF) (50% penalty if mismatched).",
    "종말의 심연 아마게돈": "Abyssal Armageddon of Ruin",
    "[사제·마법 특화] 적 전체 160% 신화급 파멸 피해 + 1턴 기절 & 5턴 공허 침식(공/방 50% 감소)": "[Priest/Mage Focus] All enemies: 160% Ruin DMG + 1-turn Stun & 5-turn Void Corruption (-50% ATK/DEF)",
    "[후열 저격] 적의 방어력을 80% 무시하고 150% 관통 피해": "[Backline Snipe] Ignores 80% DEF, dealing 150% Piercing DMG.",
    "적 전체에 80% 대미지 + 3턴간 중독(누적 지속 피해)": "Deals 80% DMG to all enemies + inflicts 3-turn Poison (cumulative DoT).",
    "[후열 저격] 적 후열에 380% 치명타 일격을 가하고 은신": "[Backline Snipe] Deals 380% Critical DMG to backline and enters Stealth.",
    "적 전체에 120% 방어무시 참격 피해": "Deals 120% slash DMG ignoring defense to all enemies.",
    "적 1체에 130% 피해 + 2턴간 회피율 60% 증가 및 피격 시 즉시 반격": "Deals 130% DMG to an enemy; self Evasion +60% for 2 turns and counters immediately on hit.",
    "[전열 특화] 적 1체에게 4연속 고속 참격 (총 170% 피해, 치명타율 +40%)": "[Front Focus] Slashes an enemy 4 times in rapid succession (170% total DMG, Crit Rate +40%).",
    "적에게 173% 마법 대미지.": "Deals 173% Magic DMG to an enemy.",
    "모든 적에게 81% 화염 광역 피해 및 화상 부여.": "Deals 81% Fire AoE DMG to all enemies and inflicts Burn.",
    "적 전체에 104% 전격 마법 피해 + 60% 기절.": "Deals 104% Lightning Magic DMG to all enemies + 60% stun chance.",
    "적 전체에 81% 빙결 피해 및 동상/냉각(행동 불가) 부여.": "Deals 81% Frost DMG to all enemies and inflicts Frostbite/Freeze (stun).",
    "적 전체를 한 점으로 응축하여 184% 피해 및 1턴 기절(행동 불가).": "Condenses all enemies to a focal point for 184% DMG and 1-turn Stun (immobilized).",
    "적 전체에 173% 지속 비전 대미지.": "Deals 173% continuous Arcane DMG to all enemies.",
    "전장에 거대 천체 유성을 낙하시켜 적 전체에게 253% 파멸 마법 피해를 입히고 3턴간 화상(지속 피해 및 방어 50% 분쇄)을 부여합니다.": "Calls down a massive astral meteor dealing 253% Ruin Magic DMG to all and inflicting 3-turn Burn (DoT & 50% DEF shred).",
    "최저 HP 아군의 체력을 150% 회복.": "Restores 150% HP to the lowest HP ally.",
    "적 1체에 115% 신성 피해 및 2턴간 실명 부여.": "Deals 115% Holy DMG to an enemy and inflicts 2-turn Blind.",
    "사망 임박(사경) 상태인 아군 1명을 부활시켜 체력 1로 소생시킵니다. (사망/사경 아군 없을 시 최저 체력 아군 115% 치유)": "Resurrects 1 ally near death with 1 HP (heals lowest HP ally for 115% if none near death).",
    "적 전체에 120% 대검 충격파를 가해 2턴간 공격력을 30% 약화시키고 모든 아군에게 최대 HP 25% 보호막을 부여합니다.": "Strikes all enemies with 120% shockwave, reducing ATK by 30% for 2 turns and shielding allies for 25% Max HP.",
    "[후열 저격] 시공간을 가르는 파멸 탄환을 발사하여 방어력을 100% 관통하고 280% 위력으로 공격합니다. (체력 40% 이하 대상 처형)": "[Backline Snipe] Fires spacetime doom round piercing 100% DEF for 280% DMG (executes targets with HP <= 40%).",
    "아군 전체에게 영웅 최대 HP 50%의 보호막을 3턴간 전개하고, 2턴간 모든 피격에 130% 상시 반격 태세에 돌입합니다.": "Shields all allies for 50% Max HP for 3 turns and adopts a 130% counter-stance on hit for 2 turns.",
    "[전열 특화] 적 1체에게 260% 신성 물리/마법 복합 피해를 입히고 가한 피해의 100%만큼 최저 HP 아군을 치유합니다.": "[Front Focus] Deals 260% Holy hybrid DMG to an enemy and heals lowest HP ally for 100% of damage dealt.",
    "적 전체에 200% 신성 강타를 가하고, 가한 피해량만큼 파티 전원 체력을 회복하며, 사망/사경 상태의 아군을 체력 1로 즉시 부활시킵니다.": "Smites all enemies for 200% Holy DMG, healing party for damage dealt and reviving fallen allies with 1 HP.",
    "[전열 특화] 전열 적에게 280% 물리 참격을 가하고 2턴간 적의 공격력을 35% 감소시키며 가한 피해의 30%를 흡혈합니다.": "[Front Focus] Slashes front foes for 280% Physical DMG, reducing their ATK by 35% for 2 turns and lifestealing 30%.",
    "자신에게 2턴간 [은신]을 부여하고 다음 공격 치명타율 100% 확정 및 치명타 피해 80% 추가 증폭 버프를 획득합니다.": "Grants self [Stealth] for 2 turns, guaranteed 100% Critical Hit, and +80% Critical damage on next attack.",
