    "공격력 +24, 치명타율 +7%, 활 전용 [화염 화살] 부여 (화상 부여 / 기본 공격 대체)": "ATK +24, Crit Rate +7%, Grants Bow-only [Flame Arrow] (Burn / Replaces basic attack)",
    "지옥불의": "Inferno",
    "공격력 +28, 방어 관통 15%, 총 전용 [유황탄 사격] 부여 (화상 부여 / 기본 공격 대체)": "ATK +28, Armor Pen 15%, Grants Gun-only [Brimstone Shot] (Burn / Replaces basic attack)",
    "맹독의": "Venomous",
    "공격력 +22, 속도 +8, 치명타율 +6%, 단검 전용 [맹독 비수] 부여 (중독 부여 / 기본 공격 대체)": "ATK +22, SPD +8, Crit Rate +6%, Grants Dagger-only [Venomous Dagger] (Poison / Replaces basic attack)",
    "영구동토의": "Permafrost",
    "공격력 +22, 마나 +120, 지팡이 전용 [혹한의 서리꽃] 부여 (빙결 부여 / 기본 공격 대체)": "ATK +22, MP +120, Grants Staff-only [Frostflower of Cold] (Freeze / Replaces basic attack)",
