    "Gate Lv.6 필요": "Requires Gate Lv.6",
    "차원 앵커 게이트를 6레벨 이상으로 증축하여 영지 침공이 열리면, 3대 방어 거점(차원 보호막, 좌/우 포탑)에 용병을 탑승시켜 영지를 수호할 수 있습니다.": "When Territory Invasion unlocks at Gate Lv.6+, station mercenaries at 3 defense strongholds (Barrier, Left/Right Turrets) to protect your citadel.",
    "수비 거점 결속 프로토콜": "Defense Bastion Binding Protocol",
    "전열 타워는 전열 특화 스킬 대상이 되며 성벽을 엄호하고, 후열 보호막은 후열 저격 대상이 됩니다.": "Frontline towers guard the wall against front-row targeting, while the backline barrier is targeted by back-row snipes.",
