    "공격 1~3차(화력·화상·중독) · 방어 1~3차(수복·기절·결빙) · 유틸 1~3차(속도%·마나%·행운%)": "ATK Tiers 1-3 (Power/Burn/Poison) · DEF Tiers 1-3 (Repair/Stun/Freeze) · UTIL Tiers 1-3 (Speed%/Mana%/Luck%)",
