    "우측 전술 포탑 사수 지정 (마법/힐러 권장)": "Assign Right Turret Gunner (Magic/Healer Recommended)",
    "수성 오퍼레이터 임명 (전술 조율)": "Appoint Defense Operator (Tactical Tuning)",
    "결속 용병은 직접 공격하지 않고, 자신의 MaxHP와 DEF를 차원 보호막에 100% 가산 합산합니다. 탱커를 배치할수록 보호막이 극적으로 두터워집니다.": "The bound hero does not attack directly, but adds 100% of their MaxHP and DEF to the barrier. Placing a tank creates a massive fortress shield.",
    "좌측 타워에 탑승한 사수는 타워의 생존/속도 스탯을 바탕으로 자신의 공격력과 스킬로 공격합니다. 기본 공격 버프(2연타 등)가 발동됩니다.": "The gunner in the left tower attacks using their ATK and skills with tower survivability and speed. Basic attack buffs (e.g. double strike) apply.",
    "우측 타워에 탑승한 사수는 타워의 생존/속도 스탯을 바탕으로 자신의 공격력과 스킬로 공격합니다. 전술 스킬 버프(쿨다운/계수)가 발동됩니다.": "The gunner in the right tower attacks with their stats and skills, augmented by tactical skill buffs (reduced cooldown/increased ratio).",
