    "차원 보호막에 결속되어 후열에서 영지를 엄호합니다. 수호자는 직접 공격하지 않는 대신 자신의 MaxHP(35% 증폭 반영)와 방어력(50%)을 영지 전체 보호막에 가산하여 철벽을 형성합니다.": "Bound to the dimensional barrier to guard the citadel from the back row. Does not attack, but adds 35% of MaxHP and 50% DEF to form an ironclad wall.",
