    "증폭!": "Boosted!",
    "보호막 방어력 (DEF)": "Barrier DEF",
    "성벽은 후열(Back Row) 판정으로, 전열 포탑들이 건재할 경우 전열 관통/후열 저격 스킬을 제외한 일반 공격으로부터 엄호받습니다.": "The wall counts as Back Row, shielded from normal attacks while front turrets stand, unless hit by row-piercing or sniper skills.",
    "좌측 전술 포탑에 탑승하여 전열 요격을 전담합니다. 포탑 기본 공격력에 사수의 공격력(ATK 100%)이 합산되며, 매 턴 타워 요격 사격과 사수의 공격 스킬을 구사합니다.": "Stations at the left turret for frontline interception. 100% of Gunner ATK is added to base turret ATK, executing intercept shots and skills each turn.",
    "포탑 총 공격력 (ATK)": "Turret Total ATK",
    "사수 공격력 합산!": "Gunner ATK Added!",
    "포탑 내구 & 속도": "Turret HP & SPD",
    "포탑 구사 스킬": "Turret Active Skills",
    "기본 사격": "Basic Shot",
    "포탑 요격 사격 (화력 버프 적용)": "Turret Intercept Shot (Firepower Buff Applied)",
    "사수 스킬": "Gunner Skill",
    "포탑은 전열(Front Row) 판정으로, 적의 전열 특화 스킬 대상이 되며 후열의 성벽을 방패처럼 보호합니다.": "Turrets count as Front Row, becoming targets for frontline skills while shielding the wall like a fortress vanguard.",
    "우측 전술 포탑에 탑승하여 전열 지원 및 디버프를 전담합니다. 포탑에 사수의 마나(MaxMP)와 행운(LUCK)이 가산되어 성벽/포탑 긴급 수복 및 전술 스킬 발동을 극대화합니다.": "Stations at the right turret for support and debuffs. Gunner MaxMP and LUCK are added to maximize repair and tactical skill triggers.",
    "포탑 최대 마나 (MP)": "Turret Max MP",
    "사수 마나 합산!": "Gunner MP Added!",
    "포탑 행운 (LUCK)": "Turret LUCK",
    "사수 행운 합산!": "Gunner LUCK Added!",
    "성역 결계 사격 (방호 마력 방출)": "Sanctuary Barrier Shot (Protective Mana Release)",
    "전술 지원": "Tactical Support",
    "우측 포탑은 전열(Front Row)에서 높은 마나와 행운으로 침입자에게 감속/결빙/기절 디버프를 가하고 성벽을 치유합니다.": "The right turret inflicts slow/freeze/stun debuffs on invaders with high Mana and Luck while restoring the wall.",
    "수성 사령탑으로 임명되어 매 4턴마다 영지 전체 부대에 전술 명령을 하달합니다. 오퍼레이터의 성향과 클래스 역할이 영지의 방어 전략 성패를 결정짓습니다.": "Appointed as the siege command post to issue tactical orders every 4 turns. The operator's Trait and Class dictate the defense strategy.",
    "매 4턴 자동 하달": "Auto Issued Every 4 Turns",
    "오퍼레이터는 전장에 직접 전투원으로 서지 않으며, 안전한 사령실에서 아군 방어 부대 전체에 버프를 부여하고 적을 약화시킵니다.": "The operator stays in the secure command room rather than the front line, buffing defense forces and debilitating foes.",
    "의 고유 전투 스킬": "'s Combat Skills",
