    "차원 앵커 게이트(Lv.3+)가 개방되어 활성화된 상태에서만 침식과 약탈이 발생합니다. 차원 앵커가 닫혀 있는 동안에는 네메시스 침공과 자원 약탈이 전면 중단되어 영지 자원이 100% 안전하게 보호됩니다.": "Erosion and plundering only occur when the Dimensional Anchor Gate (Lv.3+) is opened and active. While the Anchor is closed, Nemesis incursions and resource looting are completely halted, ensuring 100% security for citadel resources.",
