    "이미 모든 슬롯에 최적의 장비를 장착 중이거나 교체할 더 좋은 미장착 장비가 없습니다.": "Already equipped with the best gear, or no better unequipped gear is available.",
    "최적 장비 일괄 장착 완료": "Auto Equip Complete",
    "{0}의 추천 장비 {1}개를 일괄 장착했습니다.": "Auto-equipped {1} recommended gear item(s) on {0}.",
    "장착 장비": "Equipped Gear",
    "전체 장비 관리 / 일괄 판매": "Manage Gear / Bulk Sell",
    "심연 돌파 정예 보급 세트": "Elite Abyssal Breakthrough Kit",
    "에테르 횃불의 밝은 빛과 던전 도시락의 원기, 심연 곡괭이의 파쇄력으로 미지의 심연을 전격 돌파하는 정예 원정 보급 세트입니다.": "An elite expedition supply kit equipped with the radiant light of Ether Torches, revitalizing Dungeon Lunchboxes, and crushing power of Abyssal Pickaxes to breach the unknown abyss.",
    "파티 피해 감소 4% & 행동속도 +5": "Party DMG Reduction +4% & SPD +5",
    "성역 축성 퇴마 보급 세트": "Sacred Consecration Exorcism Kit",
    "여신의 성수와 성유 붕대의 정화력, 황금 열쇠와 심연의 닻이 지닌 차원 결계로 마물의 저주와 위기를 극복하는 최고위 퇴마 구비품입니다.": "Supreme exorcism supplies overcoming curses and abyssal perils through the purification of Goddess Holy Water and Holy Oil Bandages, alongside dimensional warding Golden Keys and Abyssal Anchors.",
    "파티 방어력 +18 & 최대 HP +100 & 행운 +6": "Party DEF +18, Max HP +100 & LUK +6",
    "공허 방직과 비전 직조록": "Void Weaving & Arcane Loom",
    "심연의 약초 정기와 정령 실크를 공허 파편 및 마력 수정의 비전 파동과 교직하여 마도 방벽과 마나 순환을 극대화합니다.": "Interweave abyssal herbal essence and elemental silk with the arcane resonance of void shards and magic crystals to reinforce barriers and mana circulation.",
    "파티 최대 MP +60 & 모든 피해 +5%": "Party Max MP +60 & All DMG +5%",
    "심연 골편과 암흑 정련술": "Abyssal Boneforge & Dark Smelting",
    "억센 마수 골격과 질긴 가죽을 흑연의 고열과 암흑 정수, 순수 접두석의 파동으로 담금질하여 무구의 파괴력을 극한으로 끌어올립니다.": "Temper tough beast bones and resilient leather in high-heat coal, dark essence, and pure prefix stones to draw forth devastating striking force.",
    "파티 공격력 +20 & 치명타율 +4%": "Party ATK +20 & Crit Rate +4%",
    "순수 마도석과 비전 융합록": "Pure Runestones & Arcane Fusion",
    "심연 심층에서 채취한 순수 접두·접미석의 양극 마력을 마력 수정과 정령 실크의 유연함으로 융합시켜 전역 능력치를 고루 각성시킵니다.": "Harmonize the dual polarities of pure prefix and suffix stones with magic crystals and elemental silk to awaken all attributes across the party.",
