    "견습 기사 ➔ [성기사 ➔ 발키리] / [중장 보병 ➔ 포트리스] ➔ 👑 이지스 바스티온": "Squire ➔ [Paladin ➔ Valkyrie] / [Guardian ➔ Fortress] ➔ 👑 Aegis Bastion",
