    // ── 공성/수성 전술 설명 보강 (siegeTactics.ts) ──
    "공성 3인의 공격력/방어력을 15% 균등 증폭하고 차원 보호막에 150% 안정적 피해": "Amplifies ATK and DEF of all 3 siege heroes by 15% and deals a steady 150% damage to the Dimensional Barrier",
    "자신의 방어력 수치를 공격력으로 치환하여 차원 보호막에 220%의 무자비한 분쇄 타격": "Converts own DEF into ATK to unleash a ruthless 220% crushing blow upon the Dimensional Barrier",
    "보호막에 170% 신성 피해를 입히고 공성 아군 전원의 약화 디버프를 즉시 100% 정화": "Deals 170% holy damage to the barrier and immediately cleanses 100% of weakening debuffs from all siege allies",
    "차원 보호막의 역장 접합부를 찔러 200% 방어 무시 관통 피해 및 치명타 확정": "Pierces the forcefield seam of the Dimensional Barrier for a guaranteed critical hit dealing 200% defense-ignoring damage",
    "보호막에 170% 물리 피해를 가하고 적 타워 1기의 방어력을 40% 영구 분쇄": "Deals 170% physical damage to the barrier and permanently shatters 40% DEF of 1 enemy turret",
    "보호막 전면에 가시 덫을 깔아 침입자 전면에 물리 방어력을 25% 깎고 근접 공격 반사": "Lays thorn traps in front of the barrier, reducing invader vanguard P.DEF by 25% and reflecting melee attacks",
    "보호막 전면에 가시 덫을 깔아 침입자 전열의 물리 방어력을 25% 깎고 근접 공격 반사": "Lays thorn traps in front of the barrier, reducing invader vanguard P.DEF by 25% and reflecting melee attacks",
    "보호막을 우회 침투하여 적 수비 타워 1기를 2턴간 완전 기능 정지(스턴) 및 140% 피해": "Bypasses the barrier to infiltrate and completely disable (Stun) 1 enemy turret for 2 turns while dealing 140% damage",
    "공성 딜러가 행동할 때마다 40% 확률로 기습 반격을 가해 행동 게이지를 25% 감속": "40% chance to launch an ambush counterattack whenever a siege dealer acts, slowing their action gauge by 25%",
    "물리와 비전 속성이 융합된 복합 190% 피해로 차원 보호막의 마법 저항을 30% 파괴": "Deals 190% hybrid physical/arcane damage and destroys 30% of the Dimensional Barrier's magic resistance",
    "침입자 전원에게 맹독 표창을 투사하여 3턴간 턴마다 마나 15 소실 및 지속 피해": "Hurls venomous darts at all invaders, draining 15 mana and dealing DoT each turn for 3 turns",
    "매 턴 공성 3인의 일반 공격에 차원 보호막 추가 고정 대미지 +15% 부가": "Adds +15% bonus true damage against the Dimensional Barrier to all 3 siege heroes' basic attacks every turn",
    "수비대 영웅 1명이 빈사 상태가 되면 은신을 부여하고 체력 25% 긴급 회복": "Grants Stealth and an emergency 25% HP heal when a defending hero falls into critical condition",
