    "좌측 화력 포탑의 공격 코어를 증폭하여 포탑 기본 공격력 및 포격 위력을 대폭 향상시킵니다.": "Amplifies the Left Tactical Turret's attack core, greatly increasing base ATK and bombardment power.",
    "작열 고열탄 (화상)": "Scorching Incendiary Shells (Burn)",
    "좌측 화력 포탑 포격 시 대상에게 작열 화상(Burn)을 부여합니다. 대상의 방어력이 50% 분쇄되고 매 턴 대상 최대 HP 8%의 화염 지속 피해를 입힙니다.": "Inflicts Scorching Burn on hit when the Left Tactical Turret fires, shattering 50% DEF and dealing 8% Max HP fire DoT each turn.",
    "맹독 부식탄 (중독)": "Venomous Corrosive Shells (Poison)",
    "좌측 화력 포탑 탄두에 치명적인 신경 맹독을 코팅하여 대상에게 맹독(Poison)을 부여합니다. 매 턴 대상 최대 HP 14%의 치명적 맹독 피해를 입힙니다.": "Coats Left Tactical Turret warheads in lethal neurotoxin to inflict Poison, dealing 14% Max HP venom DoT each turn.",
    "나노 결계 복원 (성벽 회복)": "Nano Barrier Restoration (Barrier Heal)",
    "우측 전술 포탑의 나노 복구 장치를 증폭하여 차원 보호막 및 포탑의 회복량을 대폭 향상시키고 매 턴 재생합니다.": "Amplifies the Right Defense Turret's nano-repair module, greatly boosting Dimensional Barrier & turret repair and regenerating HP each turn.",
    "충격 전자기파 (기절)": "Shock EMP Wave (Stun)",
    "우측 전술 포탑이 위상 간섭 방출 시 침입자를 1턴간 완전히 행동 불가로 만드는 기절(Stun) 상태이상을 유발합니다.": "Allows the Right Defense Turret's phase interference to inflict 1-turn Stun, completely immobilizing an invader.",
    "극저온 동결 역장 (결빙)": "Cryo Freeze Field (Freeze)",
    "우측 전술 포탑이 절대영도 냉각 펄스를 투사하여 침입자들을 냉각(Freeze) 상태이상에 빠뜨려 행동 불가 및 턴당 4% 동상 피해를 입힙니다. (방어력 +40%)": "Projects an absolute-zero pulse from the Right Defense Turret to Freeze invaders, immobilizing them and dealing 4% Max HP frostbite DoT (+40% DEF).",
    "중력 감속 왜곡장 (속도 감소)": "Gravity Slow Distortion (SPD Down)",
    "전장 전체에 차원 중력 왜곡장을 형성하여 침입자(적군) 전체의 속도(SPD)를 비율(%)로 지속 감속시킵니다.": "Forms a dimensional gravity distortion field across the battlefield, continuously reducing all invaders' SPD by a percentage.",
    "에테르 교란 균열 (마나 증가)": "Ether Disruption Rift (MP Cost Up)",
    "차원의 에테르 흐름을 교란하여 침입자가 스킬을 발동할 때 소모되는 마나(MP)를 비율(%)로 추가 증가시킵니다.": "Disrupts dimensional ether flow, increasing the MP cost of all invader skills by a percentage.",
    "불운의 위상 저주 (행운 감소)": "Phase Curse of Misfortune (LUCK Down)",
    "침입자 부대를 에워싸는 위상 저주를 투사하여 침입자 전체의 치명타 및 회피 판정 행운(LUCK)을 비율(%)로 대폭 감소시킵니다.": "Projects a phase curse around the invading squad, reducing all invaders' LUCK (CRIT & Evasion) by a percentage.",
