    "[전사]": "[Fallen]",
    "전사한 용병은 스킬을 변경할 수 없습니다.": "Fallen mercenaries cannot change skills.",
    "사경을 헤매다 끝내 전사한 대원입니다. [긴급 이송] 탭에서 유해를 방주(영주 성채 묘지)로 운구하고 대기소의 후방 지원 용병을 소환하세요.": "This member has fallen in battle. Use the [Emergency Transport] tab to evacuate their remains to the Ark (Citadel Graveyard) and call a reserve mercenary from the barracks.",
    "🚚 긴급 이송으로 유해 운구하기": "🚚 Evacuate Remains via Emergency Transport",
    "⚔️ 현재 장착 스킬 슬롯 (교체할 슬롯을 클릭)": "⚔️ Equipped Skill Slots (Click a slot to swap)",
    "👈 선택됨": "👈 Selected",
    "장착된 스킬 없음": "No Skill Equipped",
    "습득한 스킬이 없습니다. 마도서를 통해 새로운 스킬을 습득해보세요.": "No learned skills. Learn new skills using Grimoires.",
    "위치:": "Pos:",
    "자유 위치": "Any Position",
    "심연 탐험 중 위기에 처한 생존 용병을 방주로 무사 귀환시키거나, 끝내 사경을 넘지 못하고 완전 전사한 용병의 유해를 영주(성채 묘지)로 안전히 운구하여 유품을 회수하고 방주 대기소의 후방 용병을 원정대로 호출합니다.": "Safely return a surviving mercenary in danger to the Ark, or evacuate the remains of a fallen mercenary to the Citadel Graveyard to recover their heirlooms while calling a reserve mercenary from the Ark barracks to join the expedition.",
    "심연의 닻 적용 중: 고대 시공간 안정화 권능으로 기본 이송 턴이 2턴으로 단축됩니다! (일반 균열의 닻 3턴 ➔ 2턴)": "Abyssal Anchor Active: Ancient spacetime stabilization reduces base transport time to 2 turns! (Standard Rift Anchor 3T ➔ 2T)",
    "심연의 닻 적용 중: 고대 시공간 안정화 권능으로 기본 이송 턴이 2턴으로 단축됩니다! (일반 균열의 닻 3턴": "Abyssal Anchor Active: Ancient spacetime stabilization reduces base transport time to 2 turns! (Standard Rift Anchor 3T",
    "2턴)": "2T)",
    "균열의 닻 적용: 소환된 대원은 차원 균열을 통해 3턴 후 원정대에 도착하여 합류합니다.": "Rift Anchor Active: The summoned ally arrives and joins the expedition through the dimensional rift after 3 turns.",
    "시공간의 나침반 활성화: 초월 시공간 왜곡 권능으로 대기 턴 없이 즉시 합류(0턴)합니다!": "Compass of Spacetime Active: Transcendent spacetime distortion allows immediate arrival (0 turns) with no wait!",
    "사망": "Dead",
    "⚰️ 유해 운구 필요": "⚰️ Remains Evacuation Needed",
    "심연 탐험 중 전멸": "Wiped Out During Abyss Exploration",
    "심연 백그라운드 장기 이탈 (3분 초과 전멸)": "Prolonged Background Absence in Abyss (3m+ Wipeout)",
    "방주의 결사대원": "Ark Vanguard",
    "심연의 마물": "Abyssal Fiend",
    "⚠️ [긴급 이송 진행 중] 이미 차원 이송 중인 용병이 있습니다!": "⚠️ [Emergency Transport in Progress] A mercenary is already in dimensional transit!",
    "⚠️ [아이템 부족] 긴급 이송을 위해 [균열의 닻] 또는 [심연의 닻] 1개가 필요합니다.": "⚠️ [Insufficient Items] 1 [Rift Anchor] or [Abyssal Anchor] is required for emergency transport.",
    "⚠️ [대상 오류] 출전 중인 파티원을 찾을 수 없습니다.": "⚠️ [Target Error] Deployed party member not found.",
    "⚠️ [대상 오류] 호출할 대기 용병을 찾을 수 없습니다.": "⚠️ [Target Error] Reserve mercenary to summon not found.",
    "⚠️ [대상 오류] 이미 원정대에 출전 중인 용병입니다.": "⚠️ [Target Error] This mercenary is already deployed in the expedition.",
    "⚠️ [출전 불가] 치료실에 입원 중인 용병은 소환할 수 없습니다.": "⚠️ [Cannot Deploy] Mercenaries hospitalized in the infirmary cannot be summoned.",
    "👥 [용병 관리 충전] 야영을 통해 원정대 재정비 기회를 얻었습니다. (용병 관리 가능 1/1)": "👥 [Mercenary Management Recharged] Gained a squad reorganization opportunity through camping. (Management Available: 1/1)",
    "💀 3인 원정대가 전멸... 인벤토리 소실 후 성채로 구출되었습니다.": "💀 The expedition was wiped out... Rescued to the Citadel after losing inventory.",
    "💀 원정대 전멸": "💀 Expedition Wiped Out",
    "🪦 [진혼의 묘비] 첫 심연 탐험에서 무사히 성채로 귀환했습니다. 성채 묘지를 방문하여 영령들에게 헌화하는 퀘스트가 개방되었습니다.": "🪦 [Gravestone of Requiem] Safely returned to the Citadel from your first Abyss expedition. The quest to visit the Citadel Cemetery and offer flowers to the spirits is now unlocked.",
    "🪦📜 [회고록 갱신] 첫 번째 묘비명이 새겨져 [심연의 백과 & 회고록]의 [성채 묘비명: 영원한 불꽃의 결사대] 등록 조건이 충족되었습니다!": "🪦📜 [Memoirs Updated] The first epitaph has been engraved, fulfilling the requirement for [Citadel Epitaph: Vanguard of the Eternal Flame] in [Abyssal Codex & Memoirs]!",
