  "⛏️✨ [심연 곡괭이 대성공] 심연 곡괭이의 마력으로 채굴량 2배 극대화(골드 {0}G, [{1} ×{2}], ⚙️철광석 +10)를 완벽하게 채굴했습니다!": "⛏️✨ [深淵のツルハシ大成功] 深淵ツルハシの魔力で採掘量を2倍極大化({0}Gゴールド、[{1} ×{2}]、⚙️鉄鉱石+10)를 完璧に採掘しました！",
  "⛏️✨ [심연 곡괭이 사용] 초정밀 폭격 채굴 (채굴량 2배: {0}{1} ×{2} + ⚙️철광석 +10 + 🪙{3}G)": "⛏️✨ [深淵のツルハシ使用] 超精密爆撃採掘 (採掘量2倍: {0}{1} ×{2} + ⚙️鉄鉱石+10 + 🪙{3}G)",
