    "방주 외곽 목재 벌채 시설. 영지 증축과 성화 유지 필요한 목재를 생산합니다. (Lv.5부터 골드 유지비 점진 감면: Lv.5 7% ~ Lv.10 42%)": "方舟郊外の伐採施設。領地増築と聖火維持に必要な木材を生産します。（Lv.5からゴールド維持費漸進減免: Lv.5 7% 〜 Lv.10 42%）",
    "부유성 지반 채굴 시설. 석재를 생산하며 Lv.3부터 철광석을 함께 발굴합니다. (Lv.5부터 골드 유지비 점진 감면, Lv.7부터 골드 유지비 30% 감축 및 식량 유지비 분담)": "浮遊城の地盤採掘施設。石材を生産しLv.3から鉄鉱石を共に発掘。（Lv.5からゴールド維持費漸進減免、Lv.7からゴールド維持費30%削減および食糧維持費分担）",
    "식량 정제 시설. Lv.3부터 가죽 추출, 전 레벨 틱당 생산량 80% 대폭 증산(Lv.1: 2, Lv.5: 16, Lv.10: 43) 및 [대량 배급제] 전 시설 식량 유지비 30% 감면합니다.": "食料精製施設。Lv.3から革抽出、全レベルティックあたり生産量80%大幅増産(Lv.1: 2, Lv.5: 16, Lv.10: 43)および【大量配給制】全施設食料維持費30%減免。",
    "용병 고용소. 방랑 용병을 계약 영입하며, 레벨이 오를수록 서브 퀘스트의 요구량과 보상(골드·에테르·마도석·보급품)이 강화되고 Lv.5부터 15초마다 식량(🍗)을 생산(2레벨마다 +4 증산: Lv.5=4, Lv.7=8, Lv.9=12)합니다.": "傭兵雇用所。放浪傭兵を契約加入させ、レベルが上がるほどサブクエストの要求量と報酬（ゴールド・エーテル・魔導石・補給品）が強化され、Lv.5から15秒ごとに食料(🍗)を生産（2レベルごとに+4増産: Lv.5=4, Lv.7=8, Lv.9=12）。",
    "장비 공방. 전술 무기 및 방어구 단조, 장비 강화(+10강) 및 접두/접미 인챈트를 수행합니다. (Lv.4부터 에테르 유지비 외 4G~10G 골드 유지비 소모)": "装備工房。戦術武器・防具の鍛造、装備強化(+10強化)および接頭/接尾エンチャントを実施。（Lv.4からエーテル維持費の他4G〜10Gのゴールド維持費消費）",
    "클래스 승격 시설. 1/2차 전직을 수행하며 Lv.2~5 기본 클래스 EXP 최대 +50%, Lv.6~10 1차 각성 클래스 EXP 최대 +40% 증폭합니다.": "クラス昇格施設。1次/2次転職を執行し、Lv.2〜5で基本クラスEXP最大+50%、Lv.6〜10で1次覚醒クラスEXP最大+40%増幅。",
    "에테르 연금 및 마도 시설. 에테르를 정기 생산하고 마도서 제작 및 최고 10레벨까지 강화할 수 있으며, Lv.6 시 [에테르 환류관] 마도 시설 에테르 유지비 30% 영구 감면합니다.": "エーテル錬金および魔導施設。エーテルを定期生産し魔導書制作および最高Lv.10まで強化可能。Lv.6で【エーテル還流管】により魔導施設のエーテル維持費を30%永久減免。",
    "PVP 차원 관문 및 월드 레이드. 비동기 랭킹 결투, Lv.3 시 『차원 네메시스』 레이드, Lv.6 증축 시 5인 차원 부대 타 영지 침공해 자원 30% 약탈하는 『차원 영지 침공』이 해금됩니다.": "PVP次元関門およびワールドレイド。非同期ランキング決闘、Lv.3で『次元ネメシス』レイド、Lv.6で5人部隊で他領地を侵攻し資源30%を略奪する『次元領地侵攻』が解放。",
    "PVP 차원 관문 및 월드 레이드. 비동기 랭킹 결투, Lv.3 시 『차원 네메시스』 레이드, Lv.6 증축 시 5인 차원 부대 타 영지 침공하는 『차원 영지 침공』 해금됩니다.": "PVP次元関門およびワールドレイド。非同期ランキング決闘、Lv.3で『次元ネメシス』レイド、Lv.6で5人部隊で他領地を侵攻し資源30%を略奪する『次元領地侵攻』が解放。",
