    "아군 전체의 체력을 25% 회복하고 1턴간 모든 아군에게 받는 피해 20% 경감 축복을 부여합니다.": "味方全体のHPを25%回復し、1ターン味方全員に被ダメージ20%軽減の祝福を付与。",
    "성스러운 기도로 아군 전체 체력을 50% 대량 회복하고 2턴간 재생 효과를 부여합니다.": "聖なる祈りで味方全体HPを50%大量回復し、2ターンの間再生効果を付与。",
    "분노를 터뜨려 적 1체에게 160% 강타를 날리고 2턴간 자신의 공격력을 25% 증가시킵니다.": "怒りを爆発させ敵1体に160%の強打を放ち、2ターン自身の攻撃力を25%増加。",
    "피의 광기에 휩싸여 적 1체에게 250%의 파괴적인 일격을 가합니다. (자신의 체력이 낮을수록 최대 2배)": "血の狂気に包まれ敵1体に250%の破壊的一撃を加える（自身のHPが低いほど最大2倍）。",
    "발할라의 영혼들을 소환하여 적 전체에 160% 참격을 가하고 2턴간 파티 전원의 치명타율을 20% 높입니다.": "ヴァルハラの魂を召喚し敵全体に160%の斬撃＆2ターンパーティ全員の会心率を20%増加。",
    "진형을 재정비하여 아군 전체의 체력을 20% 회복하고 2턴간 파티 공격력과 방어력을 15% 동시 강화합니다.": "陣形を再編し味方全体HPを20%回復、2ターン味方の攻撃力と防御力を15%同時強化。",
    "적 1체에게 특수 철갑탄을 발사하여 140% 물리 피해를 입히고 1턴간 기절시킵니다.": "敵1体に特殊徹甲弾を発射し140%物理ダメージ＆1ターン気絶。",
    "전술 박격포를 전개하여 적 전체에 120% 폭발 피해를 입히고 2턴간 적들의 방어력을 20% 분쇄합니다.": "戦術迫撃砲を展開し敵全体に120%爆発ダメージ＆2ターン敵の防御力を20%粉砕。",
    "숨을 멈추고 적 후열 급소를 정확히 저격하여 280%의 치명타 관통 피해를 입힙니다.": "息を殺し敵後衛の急所を狙撃、280%の会心貫通ダメージを与える。",
    "에테르 마도 라이플의 한계를 해제하여 적 1체에게 350% 마도 관통 피해를 입히고 즉시 마나를 30 충전합니다.": "エーテル魔導ライフルのリミッターを解除し敵1体に350%魔導貫通ダメージ＆即座にマナ30充電。",
    "고대 비전의 지혜를 개방하여 아군 전체의 쿨다운을 2턴 단축시키고 마나를 20씩 회복시킵니다.": "古代秘術の知恵を開放し、味方全体のクールダウンを2ターン短縮＆マナを20ずつ回復。",
    "대주교의 성스러운 축복을 내려 아군 전체의 체력을 35% 회복하고 2턴간 받는 피해를 25% 경감합니다.": "大司教の聖なる祝福を授け、味方全体HPを35%回復＆2ターン被ダメージ25%軽減。",
    "신성한 망치를 내리쳐 적 전열에 180% 신성 피해를 입히고 아군 전체의 체력을 가한 피해의 50%만큼 치유합니다.": "神聖な槌を振り下ろし前衛に180%神聖ダメージ＆与ダメージの50%分味方全体HPを回復。",
    "강철 방벽의 권능으로 아군 전체에 시전자 방어력의 150%에 달하는 철벽의 방패를 2턴간 씌웁니다.": "鋼鉄隔壁の権能で味方全体に詠唱者の防御力150%に達する鉄壁シールドを2ターン付与。",
    "칼날의 잔영을 남기며 적 전체를 5회 연속 난무하여 총 220% 물리 피해를 가하고 2턴간 자신의 회피율을 40% 올립니다.": "刃の残影を残し敵全体に5連続乱舞（合計220%物理ダメージ）＆2ターン自身の回避率+40%。",
    "시간의 흐름을 왜곡하여 모든 아군에게 즉시 1회의 추가 행동 기회를 부여합니다.": "時の流れを歪め、味方全員に即時1回の追加行動機会を付与する。",
    "신성한 십자가의 빛을 폭발시켜 적 전체에 200% 신성 피해를 가하고 아군 전체의 체력을 30% 회복합니다.": "聖なる十字架の光を爆発させ敵全体に200%神聖ダメージ＆味方全体HP30%回復。",
    "철혈의 패기를 발산하여 적 전체를 1턴간 위압(기절)시키고 아군 전체의 공격력을 3턴간 30% 증폭합니다.": "鉄血の覇気を放ち敵全体を1ターン威圧（気絶）＆3ターン味方全体の攻撃力を30%増幅。",
    "죽음의 시선을 집중하여 적 후열 대상에게 380% 치명적인 즉사급 저격을 감행합니다.": "死の視線を集中させ、敵後衛対象に380%致命的な即死級狙撃を敢行。",
    "영원의 방패 이지스를 전개하여 2턴간 모든 아군이 받는 피해를 50% 절대 경감하고 디버프를 차단합니다.": "永遠の盾イージスを展開し、2ターンの間味方全員の被ダメージを50%絶対軽減＆デバフ完全遮断。",
    "공허의 심연 속으로 다이브하여 적 전체에게 260% 암흑 관통 피해를 입히고 1턴간 적 전체를 실명시킵니다.": "虚空の深淵へとダイブし敵全体に260%暗黒貫通ダメージ＆1ターン敵全体を盲目化。",
    "시공간 특이점을 폭발시켜 적 전체에 300% 시공간 마법 피해를 입히고 적들의 모든 버프를 해제합니다.": "時空間特異点を爆発させ敵全体に300%時空間魔法ダメージ＆敵の全バフを解除。",
