    "무적의 군세를 지휘하여 적 전체를 260% 위력으로 짓밟고 모든 아군에게 최대 HP 40% 보호막을 부여합니다.": "無敵の軍勢を率い敵全体を威力260%で蹂躙＆味方全員に最大HP40%シールド付与。",
    "[후열 저격] 대상의 방어력과 보호막을 100% 무시하고 180% 암흑 관통 피해 (치명타율 +70%)": "[後衛狙撃] 防御力とシールドを100%無視し180%暗黒貫通ダメージ（会心率+70%）。",
    "자신에게 2턴간 [은신] 부여 및 다음 공격 대미지 100% 폭풍 증폭": "自身に2ターン[潜伏]付与＆次ターンの攻撃ダメージを100%爆発的増幅。",
    "[후열 저격] 시공간을 가르는 파멸 탄환을 발사하여 방어력을 100% 관통하고 280% 위력으로 공격합니다. (체력 40% 이하 시 2배 즉사급 대미지)": "[後衛狙撃] 時空を穿つ破滅弾で防御力100%貫通の威力280%攻撃（HP40%以下で2倍即死級）。",
    "[전열 특화] 아군 전체에 2턴간 방어력 50% 증폭 및 자신에게 최대 체력 35% 보호막 생성": "[前衛特化] 味方全体に2ターン防御力50%増幅＆自身に最大HP35%シールド生成。",
    "[전열 특화] 전열 적 1체에게 자신의 방어력의 380%에 달하는 신성 물리 충격파를 가하고 1턴간 기절시킵니다.": "[前衛特化] 前衛の敵1体に自身の防御力380%に達する神聖物理衝撃波＆1ターン気絶。",
    "아군 전체에게 영웅 최대 HP 50%의 보호막을 3턴간 전개하고, 2턴간 모든 피격에 130% 상시 반격 태세를 취합니다.": "味方全体に最大HP50%シールドを3ターン展開＆2ターン被弾時130%常時反撃態勢。",
    "[전열/후열 대응] 적 1체에게 350% 치명타 일격을 가하고 2턴간 회피율 40% 증가 및 은신 상태로 진입합니다.": "[前衛/後衛対応] 敵1体に350%会心一撃＆2ターン回避率40%増加＆潜伏突入。",
    "적 전체를 가로지르며 6연속 환영 난무를 펼쳐 180% 광역 물리 피해를 입히고 적들의 공격력을 30% 감소시킵니다.": "敵全体を駆け抜け6連続幻影乱舞で180%広域物理ダメージ＆敵の攻撃力30%減少。",
    "[전열] 적 전체를 가로지르며 적의 방어력을 100% 무시하는 200% 위력의 차원 베기 + 3턴간 출혈을 부여합니다.": "[前衛] 敵全体を切り裂き防御力100%無視の威力200%次元斬撃＋3ターン出血付与。",
    "공간을 압축하여 적 전체에 220% 비전 마법 피해를 가하고 1턴간 시공 정지(행동 불가)를 부여합니다.": "空間を圧縮し敵全体に220%秘術魔法ダメージ＆1ターン時空停止（行動不能）。",
    "파티 전원의 모든 스킬 쿨다운을 2턴 단축하고 마나를 40 회복하며 행동속도를 +8 가속시킵니다.": "味方全体の全スキルクールダウン2ターン短縮、マナ40回復＆行動速度+8加速。",
    "적 전체에 300% 위력의 시공 폭발을 일으키고, 2턴간 화상(지속 피해) 및 2턴 완전 기절(행동 불가)을 부여합니다.": "敵全体に威力300%の時空爆発、2ターン火傷（継続ダメージ）＆2ターン完全気絶。",
    "[전열 특화] 적 1체에게 260% 신성 물리/마법 복합 피해를 입히고 가한 피해의 100%만큼 최저 HP 아군을 즉시 치유합니다.": "[前衛特化] 敵1体に260%神聖複合ダメージ＆与ダメージの100%分最低HP味方を即時治癒。",
    "아군 전체 체력을 220% 회복시키고 모든 해로운 상태이상을 즉시 정화하며 2턴간 디버프 면역 및 방어력 40% 버프를 부여합니다.": "味方全体HPを220%回復し全デバフ即時浄化＆2ターンデバフ免疫＆防御力40%バフ。",
    "적 전체에 200% 신성 강타를 가하고, 가한 피해량만큼 파티 전원 체력을 회복하며, 사망/사경 상태의 아군을 HP 50%로 부활시킵니다.": "敵全体に200%神聖強打＆与ダメージ分味方全体回復＆死亡/死線味方をHP50%で復活。",
    "[전열 특화] 전열 적에게 280% 물리 참격을 가하고 2턴간 적의 공격력을 35% 감소시키며 가한 피해의 30%를 체력으로 흡수합니다.": "[前衛特化] 前衛に280%物理斬撃＆2ターン敵攻撃力35%減少＆与ダメージ30%吸血。",
    "파티 전원의 공격력과 치명타율을 3턴간 50% 증폭하고 자신의 체력이 낮을수록 최대 100%까지 공격력이 추가 증폭됩니다.": "味方全体の攻撃力と会心率を3ターン50%増幅、自身のHPが低いほど最大100%追加増幅。",
    "적 전체 방어력을 40% 분쇄 (3턴 지속)하고, 2턴간 파티 전원에게 15% 흡혈 버프를 부여합니다.": "敵全体の防御力を40%粉砕（3ターン継続）＆2ターン味方全体に15%吸血バフ付与。",
    "[후열 관통] 적 전체를 60% 방어 관통하여 200% 고압 플라즈마 피해를 입히고 2턴간 받는 피해 30% 증폭 디버프를 부여합니다.": "[後衛貫通] 敵全体を防御力60%貫通で200%高圧プラズマダメージ＆2ターン被ダメージ30%増幅。",
    "자신에게 2턴간 [은신]을 부여하고 다음 공격 치명타율 100% 확정 및 치명타 피해 80% 추가 증폭 버프를 얻습니다.": "自身に2ターン[潜伏]付与＆次の攻撃確定会心100%＆会心ダメージ+80%追加増幅。",
