    "사망 임박(사경) 상태인 아군 1명을 부활시켜 체력 1로 소생시킵니다. (사망/사경 아군 없을 시 최저 체력 아군 115% 치유)": "死線状態の味方1名をHP1で蘇生させる（該当者がいない場合は最低HP味方を115%治療）。",
