    "고유 스킬": "固有スキル",
    "'{0}'에 대한 검색 결과가 없습니다.": "「{0}」に対する検索結果がありません。",
    "다른 키워드나 명칭을 입력해 보세요.": "別のキーワードや名称を入力してみてください。",
    "검색어 초기화": "検索ワード初期化",
    "전투 중 특정 전술 행동 시 획득, 5개 완충 시 궁극기로 FEVER 폭발": "戦闘中の特定戦術行動で獲得、5個蓄積で究極技FEVER炸裂",
    "💡 전투 중 마물의 스킬이나 아군 장비/스킬의 효과로 해당 상태이상이 부여됩니다. 상태이상 지속 턴 수 동안 해당 패널티 또는 이로운 효과가 틱마다 적용됩니다.": "戦闘中、魔物のスキルや味方装備・スキルの効果で付与。持続ターン中、毎ターン効果が適用されます。",
    "💡 적에게 {0} 상태가 부여되어 있을 때, 해당 태그가 부여된 스킬이나 기본 공격을 가하면 즉시 연계 콤보가 폭발합니다.": "敵に{0}状態が付与されている時、該当タグのスキルや通常攻撃を加えると即座に連携コンボが炸裂します。",
    "전투 중 해당 조건이 달성되면 파티 공용 FEVER 게이지 슬롯에 뱃지가 즉시 적립됩니다.": "戦闘中に条件が達成されると、パーティ共有のFEVERゲージスロットにバッジが即時蓄積されます。",
    "★ 뱃지가 5개 가득 찼을 때 영웅이 궁극기를 발동하면 조합에 따른 강력한 시너지가 폭발합니다.": "★バッジが5個満タンの時、英雄が究極技を発動すると組み合わせに応じた強力なシナジーが炸裂します。",
    "🔄 5개가 채워진 상태에서 새 뱃지를 얻으면 맨 앞의 오래된 뱃지가 밀려나며 실시간으로 최종 시너지가 갱신됩니다.": "🔄5個満たされた状態で新しいバッジを獲得すると、先頭の古いバッジが押し出され、リアルタイムで最終シナジーが更新されます。",
    "⚠️ 비적합 클래스가 장착/사용 시 전투 중 위력이 50% 반감됩니다.": "⚠️ 非適合クラスが装備・使用した場合、戦闘中の威力が50%半減します。",
    "💡 성채 용병 관리 창에서 용병에게 전수하여 새로운 액티브 스킬 슬롯을 개방할 수 있습니다.": "💡 城塞の傭兵管理画面で傭兵に伝授し、新たなアクティブスキルスロットを開放できます。",
    "특수 및 기타 클래스": "特殊およびその他クラス",
    "기타 전직 및 특수 역할군": "その他転職および特殊役割",
    "기타 특수 직업": "その他特殊職業",
    "시작 클래스(Tier 0) ➔ 1차 전직(Tier 1) ➔ 2차 각성(Tier 2) ➔ 👑 3차 초월(Tier 3)": "基本クラス (Tier 0) ➔ 1次転職 (Tier 1) ➔ 2次覚醒 (Tier 2) ➔ 👑 3次超越 (Tier 3)",
    "전투 중 마물의 스킬이나 아군 장비/스킬의 효과로 해당 상태이상이 부여됩니다. 상태이상 지속 턴 수 동안 해당 패널티 또는 이로운 효과가 틱마다 적용됩니다.": "戦闘中に魔物のスキルや味方の装備・スキルの効果によって付与されます。持続ターン中、各ペナルティや有益な効果が毎ターン発動します。",
    "상태이상 스킬 연계 콤보 메커니즘": "状態異常スキル連携コンボメカニズム",
    "전술 운용 팁:": "戦術運用のヒント:",
    "{0}을 착용한 영웅은 기본 공격 및 관련 전투 행동 시 위 고유 메커니즘이 상시 적용됩니다. 시너지 효과를 가진 클래스와 조합하면 전투 효율이 극대화됩니다.": "{0}を装備した英雄は通常攻撃や関連行動時に上記固有メカニズムが常時適用されます。シナジーを持つクラスと編成することで戦闘効率が最大化されます。",
    "최대 {0}단계까지 증축 가능하며, 레벨이 상승함에 따라 생산량이 비약적으로 증가하거나 새로운 제작 레시피 및 특수 기능이 해금됩니다. 시설 Lv.4부터는 골드 또는 식량 등의 유지비가 부과될 수 있습니다.": "最大Lv.{0}まで増築可能で、レベル上昇に伴い生産量が飛躍的に増加し、新たな製作レシピや特殊機能が解放されます。Lv.4からはゴールドや食料などの維持費が発生する場合があります。",
    "적에게 {0} 상태가 부여되어 있을 때, 해당 태그가 부여된 스킬이나 기본 공격을 가하면 즉시 연계 콤보가 폭발합니다.": "敵に{0}状態が付与されている時、該当タグが付与されたスキルや通常攻撃を行うと即座に連携コンボが発動します。",
