    "병기창에서 마도석을 소비하여 해당 부위의 장비 슬롯에 각인할 수 있습니다.": "兵器廠で魔導石を消費し、該当部位の装備スロットに刻印できます。",
    "방주 비사 및 시설 뒷이야기": "方舟秘史および施設裏話",
