    "에테르 공방에서 용병의 스킬을 1회 강화하여 비전 전술 능력을 증폭하세요.": "エーテル工房で傭兵のスキルを1回強化し、秘伝戦術能力を増幅させてください。",
    "에테르 공방에서 스킬 강화 1회": "エーテル工房でスキル強化1回",
