    "Gate Lv.6 필요": "Gate Lv.6 必要",
    "차원 앵커 게이트를 6레벨 이상으로 증축하여 영지 침공이 열리면, 3대 방어 거점(차원 보호막, 좌/우 포탑)에 용병을 탑승시켜 영지를 수호할 수 있습니다.": "次元アンカーゲートをLv.6以上に増築して領地侵攻が解放されると、3大防衛拠点(次元シールド、左/右砲塔)に傭兵を配置して領地を防衛できます。",
    "수비 거점 결속 프로토콜": "守備拠点結束プロトコル",
