    "총": "合計",
    "공격 1~3차(화력·화상·중독) · 방어 1~3차(수복·기절·결빙) · 유틸 1~3차(속도%·마나%·행운%)": "攻撃 1~3次(火力・火傷・中毒) · 防御 1~3次(修復・気絶・氷結) · 補助 1~3次(速度%・マナ%・幸運%)",
