    "차원 보호막 결속자 지정 (탱커 권장)": "次元シールド結束者の指定 (タンク推奨)",
    "좌측 전술 포탑 사수 지정 (물리 딜러 권장)": "左側戦術砲塔 射手指定 (物理DPS推奨)",
