    "수성 오퍼레이터 임명 (전술 조율)": "守城オペレーター任命 (戦術調整)",
    "결속 용병은 직접 공격하지 않고, 자신의 MaxHP와 DEF를 차원 보호막에 100% 가산 합산합니다. 탱커를 배치할수록 보호막이 극적으로 두터워집니다.": "結束傭兵は直接攻撃せず、自身のMaxHPとDEFを次元シールドに100%合算します。タンクを配置するほどシールドが劇的に強化されます。",
    "좌측 타워에 탑승한 사수는 타워의 생존/속도 스탯을 바탕으로 자신의 공격력과 스킬로 공격합니다. 기본 공격 버프(2연타 등)가 발동됩니다.": "左タワーの射手はタワーの生存/速度をベースに自身の攻撃力とスキルで迎撃します。基本攻撃バフ(2連撃など)が発動します。",
    "우측 타워에 탑승한 사수는 타워의 생존/속도 스탯을 바탕으로 자신의 공격력과 스킬로 공격합니다. 전술 스킬 버프(쿨다운/계수)가 발동됩니다.": "右タワーの射手はタワーの生存/速度をベースに攻撃し、戦術スキルバフ(クールダウン/倍率)が発動します。",
    "오퍼레이터의 성향(8종)과 클래스(6종)에 따라 영지의 핵심 수성 전술이 발동됩니다.": "オペレーターの特性(8種)とクラス(6種)に応じて領地の重要守城戦術が発動します。",
