    "전황 총괄 지휘": "戦況統括指揮",
    "차원 보호막에 결속되어 후열에서 영지를 엄호합니다. 수호자는 직접 공격하지 않는 대신 자신의 MaxHP(35% 증폭 반영)와 방어력(50%)을 영지 전체 보호막에 가산하여 철벽을 형성합니다.": "次元シールドに結束し後列から領地を援護します。直接攻撃は行いませんが、MaxHP(35%増幅反映)と防御力(50%)をシールド全体に加算して鉄壁を築きます。",
    "보호막 총 내구도 (HP)": "シールド総耐久度 (HP)",
    "증폭!": "増幅！",
    "보호막 방어력 (DEF)": "シールド防御力 (DEF)",
    "성벽은 후열(Back Row) 판정으로, 전열 포탑들이 건재할 경우 전열 관통/후열 저격 스킬을 제외한 일반 공격으로부터 엄호받습니다.": "城壁は後列(Back Row)判定となり、前列砲塔が健在な限り貫通・狙撃スキル以外の通常攻撃から保護されます。",
    "좌측 전술 포탑에 탑승하여 전열 요격을 전담합니다. 포탑 기본 공격력에 사수의 공격력(ATK 100%)이 합산되며, 매 턴 타워 요격 사격과 사수의 공격 스킬을 구사합니다.": "左側戦術砲塔に搭乗して前列迎撃を担当します。基本攻撃力に射手のATK 100%が加算され、毎ターン迎撃射撃と攻撃スキルを繰り出します。",
    "포탑 총 공격력 (ATK)": "砲塔総攻撃力 (ATK)",
    "사수 공격력 합산!": "射手攻撃力合算！",
    "포탑 내구 & 속도": "砲塔耐久＆速度",
