    "포탑 요격 사격 (화력 버프 적용)": "砲塔迎撃射撃 (火力バフ適用)",
    "사수 스킬": "射手スキル",
    "포탑은 전열(Front Row) 판정으로, 적의 전열 특화 스킬 대상이 되며 후열의 성벽을 방패처럼 보호합니다.": "砲塔は前列(Front Row)判定となり、敵の前列特化スキルの対象となりつつ後列の城壁を守る盾となります。",
