    "⚡ [진척도 가속] 묘지기의 종 강제 타종 (위험도 +25 / 원혼 토벌 시 [순교자의 피] 가호 & 유품 수습)": "⚡【進捗加速】墓守の鐘の強制打鐘 (危険度+25 / 怨霊討伐時に【殉教者の血】加護＆遺品回収)",
    "격노한 순교자의 원혼": "激昂した殉教者の怨霊",
    "묘지기의 타락한 망령": "墓守の堕ちた亡霊",
