    "봉인 깨진 납골단지 수호령": "封印解かれし納骨壺の守護霊",
    "원한 서린 유골 망령": "怨恨満ちる遺骨亡霊",
    "⚡ [진척도 가속] 동력핵 강제 추출 (위험도 +25 / 골렘 토벌 시 거신의 핵 & 방어력 +15% 가호)": "⚡【進捗加速】動力コアの強制抽出 (危険度+25 / ゴーレム討伐時に巨神の核＆防御力+15%加護)",
    "폭주하는 고대 수호 골렘": "暴走する古代守護ゴーレム",
    "과충전된 마도 수호병": "過充電された魔導守護兵",
    "⚡ [진척도 가속] 참회실 성수 강제 정화 (위험도 +25 / 흡혈귀 격퇴 시 흡혈 가호 & 은총 수습)": "⚡【進捗加速】懺悔室の聖水の強制浄化 (危険度+25 / 吸血鬼撃退時に吸血加護＆恩寵回収)",
    "참회실의 타락한 흡혈 귀족": "懺悔室の堕落した吸血貴族",
    "피에 굶주린 시종 박쥐": "血に飢えた従者コウモリ",
    "⚡ [진척도 가속] 지하 고문실 강제 돌파 (위험도 +25 / 간수 격파 시 치명타 +15% 가호 & 열쇠 수습)": "⚡【進捗加速】地下拷問室の強行突破 (危険度+25 / 看守撃破時に会心+15%加護＆鍵回収)",
    "심연의 고문실 수간수": "深淵の拷問室長看守",
    "단죄의 고문 집행관": "断罪の拷問執行官",
    "⚡ [진척도 가속] 도플갱어의 거울 깨뜨리기 (위험도 +30 / 복제본 격파 시 에테르 150 & 모든 스탯 +10% 가호)": "⚡【進捗加速】ドッペルゲンガーの鏡破壊 (危険度+30 / 複製体撃破時にエーテル150＆全ステ+10%加護)",
    "도플갱어": "ドッペルゲンガー",
    "도플갱어: ": "ドッペルゲンガー: ",
    "⚡ 경보 룬을 격발하여 마물들을 유인했습니다! (토벌 시 공격력 +15% 가호, 군번줄 수습)": "⚡ 警報ルーンを撃発して魔物を誘引しました！（討伐時に攻撃力+15%加護、認識票回収）",
    "⚡ 묘지기의 종을 강제로 타종했습니다! 분노한 원혼들이 몰려옵니다!": "⚡ 墓守の鐘を無理やり打ち鳴らしました！怒れる怨霊たちが押し寄せてきます！",
    "⚡ 고대 납골단지를 일괄 파괴했습니다! 성난 수호령들이 나타났습니다!": "⚡ 古代の納骨壺を一括破壊しました！怒れる守護霊たちが姿を現しました！",
    "⚡ 동력핵을 강제로 추출하자 거신 석상이 폭주하며 깨어났습니다!": "⚡ 動力コアを無理やり引き抜くと、巨神石像が暴走して目覚めました！",
    "⚡ 참회실을 강제 정화하자 핏빛 안개 속에서 흡혈 귀족이 모습을 드러냈습니다!": "⚡ 懺悔室を強引に浄化すると、血の霧の中から吸血貴族が姿を現しました！",
    "⚡ 지하 고문실을 강제 돌파하자 거구의 고문실 간수들이 무기를 치켜듭니다!": "⚡ 地下拷問室を強行突破すると、巨躯の拷問看守たちが武器を掲げました！",
    "⚡ 도플갱어의 거울을 깨뜨리자 원정대와 똑같은 형상의 복제본들이 거울 파편에서 걸어나왔습니다!": "⚡ ドッペルゲンガーの鏡を破壊すると、遠征隊と生き写しの複製体が鏡の破片から歩み出てきました！",
    "⚡ [가속 성공] 1층 마물들을 토벌하고 척후병의 유언 가호와 군번줄을 수습했습니다! (공격력 +15%)": "⚡【加速成功】1階の魔物を討伐し、斥候の遺言加護と認識票を回収しました！（攻撃力+15%）",
    "⚡ [가속 성공] 순교자의 원혼을 정화하고 순교자의 피 가호와 유품을 수습했습니다! (치명타 +10%, 에테르 40)": "⚡【加速成功】殉教者の怨霊を浄化し、殉教者の血加護と遺品を回収しました！（会心+10%、エーテル40）",
    "⚡ [가속 성공] 납골단지 수호령들을 퇴치하고 대량의 에테르와 전리품을 수습했습니다! (에테르 60)": "⚡【加速成功】納骨壺の守護霊を退治し、大量のエーテルと戦利品を回収しました！（エーテル60）",
    "⚡ [가속 성공] 폭주 골렘을 파괴하고 거신의 동력핵을 획득했습니다! (방어력 +15%, 에테르 50)": "⚡【加速成功】暴走ゴーレムを撃破し、巨神の動力コアを獲得しました！（防御力+15%、エーテル50）",
    "⚡ [가속 성공] 흡혈 귀족을 격퇴하고 핏빛 은총 가호를 획득했습니다! (가한 피해 10% 흡혈, 에테르 80)": "⚡【加速成功】吸血貴族を撃退し、血の恩寵加護を獲得しました！（与ダメージ10%吸血、エーテル80）",
    "⚡ [가속 성공] 고문실 간수들을 격파하고 고문실장의 열쇠와 잔혹한 기백 가호를 획득했습니다! (치명타 +15%, 에테르 100)": "⚡【加速成功】拷問看守たちを撃破し、拷問室長の鍵と残酷な気迫加護を獲得しました！（会心+15%、エーテル100）",
    "⚡ [가속 성공] 도플갱어 파티를 격파하고 초차원의 거울 파편을 획득했습니다! (모든 스탯 +10%, 에테르 150)": "⚡【加速成功】ドッペルゲンガーパーティを撃破し、超次元の鏡の破片を獲得しました！（全ステ+10%、エーテル150）",
    "비상 탈출 시도 (균열의 닻 부재)": "緊急脱出試行（亀裂のアンカー不在）",
    "비상 탈출 감행": "緊急脱出を敢行",
    "비상 탈출 위험 수칙:": "緊急脱出の危険規則:",
    "실패 시 70% 마물 추격전": "失敗時70%の確率で魔物追撃戦",
    "퇴로가 차단되어 기습 피해를 입고 추격대와 사투를 벌이며, 전투 승리 시 성채로 귀환합니다.": "退路が遮断されて奇襲ダメージを受け追撃隊と死闘を展開し、勝利時に城塞へ帰還します。",
    "정말로 모든 위험을 감수하고 비상 탈출을 감행하시겠습니까?": "本当にすべての危険を冒して緊急脱出を敢行しますか？",
    "⚠️ 닻 없이 위험을 무릅쓰고 비상 탈출 시도 (성공률 30%)": "⚠️ アンカーなしで危険を冒して緊急脱出を試みる（成功率30%）",
    "비상탈출": "緊急脱出",
