    ja: m => `⚖️✨ [聖魔一体・強打] ${trEntity(m[1].trim(), 'ja')}の治癒エネルギーが共鳴し、${trEntity(m[2].trim(), 'ja')}に${m[3]}の神聖審判強打を放ちました！`
